<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nodexa · Database Hosts</title><style>body{margin:0;font-family:Inter,system-ui;background:#0b0d12;color:#eef1f7}.wrap{max-width:1200px;margin:auto;padding:32px}.top{display:flex;justify-content:space-between;align-items:center}.card{background:#11151d;border:1px solid #202633;border-radius:14px;padding:18px;margin-top:18px}button,input,select{font:inherit}.btn{background:#695cff;color:#fff;border:0;border-radius:9px;padding:10px 14px;cursor:pointer}.secondary{background:#1a2030}.danger{background:#3a1720}table{width:100%;border-collapse:collapse;margin-top:12px}th,td{text-align:left;padding:13px;border-bottom:1px solid #202633}th{color:#7e899c;font-size:12px}.status.online{color:#63d6a6}.status.offline{color:#f48da2}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.grid label{display:flex;flex-direction:column;gap:6px;color:#a6afbf}.grid input,.grid select{background:#0b0e14;border:1px solid #2a3140;color:#fff;padding:10px;border-radius:8px}.actions{display:flex;gap:7px;flex-wrap:wrap}.secret{font-family:monospace}.muted{color:#7e899c}@media(max-width:800px){.grid{grid-template-columns:1fr}.top{align-items:flex-start;gap:12px;flex-direction:column}}</style></head><body><div class="wrap"><div class="top"><div><div class="muted">Nodexa Administration</div><h1>Database Hosts</h1></div><div class="actions"><button class="btn secondary" onclick="location.href='/'">Back to Panel</button><button class="btn" onclick="showForm()">Create Database Host</button></div></div><div id="message"></div><div class="card"><table><thead><tr><th>Name</th><th>Host</th><th>Node</th><th>Databases</th><th>Status</th><th>Actions</th></tr></thead><tbody id="rows"></tbody></table></div><div id="form" class="card" style="display:none"><h2 id="formTitle">Create Database Host</h2><div class="grid"><label>Name<input id="name"></label><label>Host / IP<input id="host" placeholder="db01.example.com"></label><label>Port<input id="port" type="number" value="3306"></label><label>Admin Username<input id="username"></label><label>Admin Password<div class="actions"><input id="password" type="password" style="flex:1"><button class="btn secondary" onclick="togglePassword()" type="button">Vis/Skjul</button></div></label><label>Allowed DB User Host<input id="remote_host" value="%"></label><label>Node<select id="node_id"><option value="">Any node</option></select></label><label>Max Databases<input id="max_databases" type="number" placeholder="Unlimited"></label><label><span>SSL</span><select id="ssl"><option value="0">Disabled</option><option value="1">Enabled</option></select></label><label><span>Enabled</span><select id="enabled"><option value="1">Enabled</option><option value="0">Disabled</option></select></label></div><div class="actions" style="margin-top:16px"><button class="btn" onclick="saveHost()">Save</button><button class="btn secondary" onclick="hideForm()">Cancel</button></div></div></div><script>
const token=localStorage.getItem('nodexa_panel_token');if(!token)location.href='/';const headers={'Authorization':'Bearer '+token,'Content-Type':'application/json','Accept':'application/json'};let hosts=[],nodes=[],editing=null;
async function api(url,opt={}){const r=await fetch(url,{...opt,headers:{...headers,...(opt.headers||{})}});if(r.status===401||r.status===403){location.href='/';throw new Error('Unauthorized')}if(!r.ok){let j={};try{j=await r.json()}catch{}throw new Error(j.message||'Request failed')}return r.status===204?null:r.json()}
async function load(){[hosts,nodes]=await Promise.all([api('/api/database-hosts'),api('/api/nodes').then(x=>x.data||x)]);render();const s=document.getElementById('node_id');s.innerHTML='<option value="">Any node</option>'+nodes.map(n=>`<option value="${n.id}">${n.name}</option>`).join('')}
function render(){document.getElementById('rows').innerHTML=hosts.map(h=>`<tr><td><b>${esc(h.name)}</b></td><td>${esc(h.host)}:${h.port}</td><td>${h.node?esc(h.node.name):'Any'}</td><td>${h.databases_count||0}${h.max_databases?' / '+h.max_databases:''}</td><td class="status ${h.last_status}">${h.last_status||'unknown'}</td><td><div class="actions"><button class="btn secondary" onclick="testHost(${h.id})">Test</button><button class="btn secondary" onclick="editHost(${h.id})">Edit</button><button class="btn danger" onclick="removeHost(${h.id})">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="muted">No database hosts configured.</td></tr>'}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function showForm(){editing=null;document.getElementById('formTitle').textContent='Create Database Host';['name','host','username','password','max_databases'].forEach(i=>document.getElementById(i).value='');document.getElementById('port').value=3306;document.getElementById('remote_host').value='%';document.getElementById('node_id').value='';document.getElementById('ssl').value='0';document.getElementById('enabled').value='1';document.getElementById('form').style.display='block'}
function hideForm(){document.getElementById('form').style.display='none'}
function editHost(id){const h=hosts.find(x=>x.id===id);editing=id;document.getElementById('formTitle').textContent='Edit Database Host';for(const k of ['name','host','port','username','remote_host','max_databases'])document.getElementById(k).value=h[k]??'';document.getElementById('password').value='';document.getElementById('node_id').value=h.node_id??'';document.getElementById('ssl').value=h.ssl?'1':'0';document.getElementById('enabled').value=h.enabled?'1':'0';document.getElementById('form').style.display='block'}
function togglePassword(){const e=document.getElementById('password');e.type=e.type==='password'?'text':'password'}
async function saveHost(){const body={name:v('name'),host:v('host'),port:+v('port'),username:v('username'),password:v('password'),remote_host:v('remote_host')||'%',node_id:v('node_id')?+v('node_id'):null,max_databases:v('max_databases')?+v('max_databases'):null,ssl:v('ssl')==='1',enabled:v('enabled')==='1'};try{await api(editing?'/api/database-hosts/'+editing:'/api/database-hosts',{method:editing?'PUT':'POST',body:JSON.stringify(body)});hideForm();await load();msg('Saved successfully')}catch(e){msg(e.message,true)}}
async function testHost(id){try{const r=await api('/api/database-hosts/'+id+'/test',{method:'POST'});msg(r.status==='online'?'Database host is online':'Database host is offline: '+(r.error||''),r.status!=='online');await load()}catch(e){msg(e.message,true)}}
async function removeHost(id){if(!confirm('Delete this database host?'))return;try{await api('/api/database-hosts/'+id,{method:'DELETE'});await load()}catch(e){msg(e.message,true)}}
function v(id){return document.getElementById(id).value}function msg(t,bad=false){document.getElementById('message').innerHTML=`<div class="card" style="border-color:${bad?'#5a2e3b':'#285948'}">${esc(t)}</div>`}
load().catch(e=>msg(e.message,true));
</script></body></html>